    n = len(pattern)
    m = len(query)

    if '*' not in pattern:
        if n != m:
            return False
        for i in range(n):
            if pattern[i] != '?' and pattern[i] != query[i]:
                return False
            if pattern[i] == '?' and query[i] not in good_set:
                return False
        return True

